overy_only": true, "content_version": "phuket-discovery-20261118", "experience_type": "activity", "location_name": "Jungceylon, Patong", "source_page_url": "https://powerdrivephuket.com/", "photo_source_url": "https://static.tildacdn.com/tild6261-3633-4630-b831-393161383764/DSC09568.jpg", "booking_url": null, "external_link": null, "short_description": null, "long_description": null, "duration_minutes": null, "min_participants": null, "max_participants": null, "available_days": [], "start_times": [], "source_type": "editorial"}}]'::jsonb) AS r(id uuid,slug text,name_en text,name_ru text,description_en text,description_ru text,category text,cover_image text,attrs jsonb))
 INSERT INTO public.listings(id,vertical,slug,name_en,name_ru,description_en,description_ru,category,cover_image,images,price,rating,review_count,is_active,is_featured,is_verified,approval_status,attributes)
 SELECT id,'experience',slug,name_en,name_ru,description_en,description_ru,category,cover_image,ARRAY[]::text[],NULL,0,0,true,false,false,'approved',attrs||jsonb_build_object('content_published_at',now()) FROM data WHERE id='5e56ab2c-683b-4fd2-a392-a971b6b71d73';
 GET DIAGNOSTICS changed = ROW_COUNT;
 IF changed <> 1 THEN RAISE EXCEPTION 'Expected one new PowerDrive record'; END IF;
END $content$;
COMMIT;
